\end{mdframed}

%======================================================================
\section{Magnets and magnetic poles}

\subsection{Starting from what you already know}
Long before any formula you already know:
\begin{itemize}
  \item a fridge magnet sticks to a steel door but not to wood;
  \item two bar magnets can attract \emph{or} repel depending on which ends face each other;
  \item a compass needle settles roughly north--south.
\end{itemize}
Physics names the ``ends'' of a magnet its \textbf{magnetic poles}.
By definition:
\begin{itemize}
  \item the end that points roughly geographic north (when free to turn) is the
        \textbf{north-seeking pole} (N-pole);
  \item the opposite end is the \textbf{south-seeking pole} (S-pole).
\end{itemize}

\subsection{Like poles repel, unlike poles attract}
\begin{center}
\begin{tikzpicture}[scale=0.95]
  \draw[thick,fill=red!25] (0,0) rectangle (1.6,0.7);
  \draw[thick,fill=blue!20] (1.6,0) rectangle (3.2,0.7);
  \node[font=\small] at (0.8,0.35) {N}; \node[font=\small] at (2.4,0.35) {S};
  \draw[thick,fill=red!25] (4.2,0) rectangle (5.8,0.7);
  \draw[thick,fill=blue!20] (5.8,0) rectangle (7.4,0.7);
  \node[font=\small] at (5.0,0.35) {N}; \node[font=\small] at (6.6,0.35) {S};
  \draw[-{Latex},thick,posC] (3.2,0.35) -- (4.2,0.35);
  \draw[-{Latex},thick,posC] (4.2,0.55) -- (3.2,0.55);
  \node[font=\scriptsize,posC] at (3.7,1.05) {repel (N--N)};
  \begin{scope}[yshift=-1.5cm]
    \draw[thick,fill=red!25] (0,0) rectangle (1.6,0.7);
    \draw[thick,fill=blue!20] (1.6,0) rectangle (3.2,0.7);
    \node[font=\small] at (0.8,0.35) {N}; \node[font=\small] at (2.4,0.35) {S};
    \draw[thick,fill=blue!20] (4.2,0) rectangle (5.8,0.7);
    \draw[thick,fill=red!25] (5.8,0) rectangle (7.4,0.7);
    \node[font=\small] at (5.0,0.35) {S}; \node[font=\small] at (6.6,0.35) {N};
    \draw[-{Latex},thick,negC] (3.35,0.35) -- (4.05,0.35);
    \draw[-{Latex},thick,negC] (4.05,0.35) -- (3.35,0.35);
    \node[font=\scriptsize,negC] at (3.7,-0.35) {attract (S--N)};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Magnetic poles always come in pairs}
You cannot isolate a single magnetic pole. If you snap a bar magnet in half,
each piece becomes a new bar magnet with its own N and S.
(There is no magnetic analogue of rubbing charge off an insulator.)

\qbfig{QB405 PHY14051101}{D}{../../../_qb-assets/QB405/p-01.png}{%
Breaking a magnet does not destroy magnetism and does not create monopoles.
Each fragment still has \textbf{two poles} $\Rightarrow$ \textbf{D}.}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistake --- ``monopoles''.}
Cutting a magnet never leaves ``only N'' or ``only S''. Every piece is still a
dipole. (Isolated magnetic monopoles have never been observed.)
\end{mdframed}

%======================================================================
\section{Magnetic field and field lines}

\subsection{What is a magnetic field?}
A magnet (or a current) alters the space around it. We describe that alteration
by a vector field $\vec B$, the \textbf{magnetic flux density} (often just called
the magnetic field).
\begin{itemize}
  \item SI unit: \textbf{tesla} (T). $1\,\mathrm{T}=1\,\mathrm{N\,A^{-1}\,m^{-1}}$.
  \item Direction of $\vec B$ at a point: the direction a tiny compass needle's
        \textbf{N-pole} would point there.
\end{itemize}

\subsection{Rules for drawing field lines}
\begin{enumerate}
  \item Lines leave N-poles and enter S-poles (outside the magnet).
  \item Lines never cross.
  \item Closer spacing $\Leftrightarrow$ stronger $|\vec B|$.
  \item Inside a long solenoid the lines are nearly parallel and equally spaced
        (approximately uniform field).
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=0.9]
  \draw[thick,fill=red!20] (-1.2,-0.35) rectangle (0,0.35);
  \draw[thick,fill=blue!15] (0,-0.35) rectangle (1.2,0.35);
  \node[font=\small] at (-0.6,0) {N}; \node[font=\small] at (0.6,0) {S};
  \foreach \y in {-0.25,0,0.25} {
    \draw[-{Latex},negC] (-2.2,\y) -- (-1.2,\y);
    \draw[-{Latex},negC] (1.2,\y) -- (2.2,\y);
  }
  \draw[-{Latex},negC] (-1.0,0.55) .. controls (-1.6,1.3) and (1.6,1.3) .. (1.0,0.55);
  \draw[-{Latex},negC] (-1.0,-0.55) .. controls (-1.6,-1.3) and (1.6,-1.3) .. (1.0,-0.55);
  \node[font=\scriptsize] at (0,-1.7) {field lines outside: N $\to$ S};
\end{tikzpicture}
\end{center}

\subsection{Symbols for into / out of the page}
\begin{center}
\begin{tikzpicture}
  \draw[thick] (0,0) circle (0.35);
  \draw[thick] (-0.18,-0.18) -- (0.18,0.18);
  \draw[thick] (-0.18,0.18) -- (0.18,-0.18);
  \node[right,font=\small] at (0.5,0) {$\otimes$ into the page};
  \draw[thick] (4.2,0) circle (0.35);
  \fill (4.2,0) circle (0.07);
  \node[right,font=\small] at (4.7,0) {$\odot$ out of the page};
\end{tikzpicture}
\end{center}

%======================================================================
\section{The Earth's magnetic field}

The Earth behaves roughly like a giant bar magnet.
\begin{itemize}
  \item Geographic North is near a \textbf{magnetic south} pole of that ``magnet''
        (so a compass N-pole is attracted toward geographic north).
  \item Field lines enter near geographic north and leave near geographic south.
  \item The field has a horizontal component (what a pivoted compass shows) and a
        vertical component (dip).
\end{itemize}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Exam wording.}
``Magnetic north pole of the Earth'' in casual speech often means the place near
geographic north where compasses point --- that location is a \textbf{magnetic
south} pole in the physics sense (field lines enter there).
\end{mdframed}

%======================================================================
\section{Magnetic fields due to currents}

Oersted's discovery: a current-carrying wire deflects a nearby compass.
Currents are sources of $\vec B$.

\subsection{Right-hand grip rule (long straight wire)}
Point your right thumb in the direction of conventional current $I$.
Your curled fingers show the sense of the circular $\vec B$ field around the wire.

\begin{center}
\begin{tikzpicture}[scale=1.05]
  % wire
  \draw[line width=2pt,-{Latex}] (0,-1.8) -- (0,2.0) node[above,font=\small] {$I$};
  \node[font=\scriptsize,align=center] at (0,-2.2) {thumb $=I$\\(up the wire)};
  % circles
  \foreach \r in {0.55,0.95,1.35} {
    \draw[-{Latex},negC,thick] ({\r},0) arc (0:300:\r);
  }
  \node[font=\scriptsize,negC] at (2.0,0.3) {$B$ circles};
  % grip sketch
  \begin{scope}[xshift=4.6cm,yshift=0.2cm]
    \draw[thick,fill=orange!20] (0,0) -- (0.9,0.35) -- (0.9,1.5) -- (0,1.15) -- cycle;
    \draw[thick,fill=orange!15] (0.15,1.2) ellipse (0.35 and 0.22);
    \draw[-{Latex},thick] (0.15,1.55) -- (0.15,2.15) node[above,font=\scriptsize] {thumb $=I$};
    \draw[-{Latex},negC,thick] (0.7,0.9) arc (-40:220:0.55);
    \node[font=\scriptsize,negC] at (1.7,0.6) {fingers $=B$};
    \node[font=\small,align=center] at (0.6,-0.55) {RH grip\\(wire)};
  \end{scope}
\end{tikzpicture}
\end{center}

\noindent\textbf{Formula} (long straight wire in vacuum / air), at perpendicular
distance $r$:
\[
B = \frac{\mu_0 I}{2\pi r},
\qquad
\mu_0 = 4\pi\times 10^{-7}\,\mathrm{T\,m\,A^{-1}}.
\]
$B$ falls as $1/r$. Direction: RH grip.

\worked{2021}{25}{C}{63}{../2021_q25.png}{%
Wire at $P$ carries $0.3\,\mathrm{A}$ into the paper.
At $R$, its field is $B_P=\mu_0(0.3)/(2\pi\cdot 0.15)$.
To cancel it, the wire at $Q$ must produce an equal field at $R$ in the
\textbf{opposite} direction, so its current must be \textbf{out of} the paper.
Distance $QR=0.05\,\mathrm{m}=PQ/2$, so
$I_Q = 0.3\times(0.05/0.15)=0.1\,\mathrm{A}$ $\Rightarrow$ \textbf{C}.}

\subsection{Circular loop / flat coil}
For a single circular turn, RH grip again: curl fingers with the current around
the loop; thumb gives $\vec B$ through the centre (the ``N-face'' of the loop).

\subsection{Long solenoid}
A solenoid is a long tightly wound coil. Inside, $\vec B$ is nearly uniform and
parallel to the axis; outside, $B\approx 0$ for an ideal long solenoid.
\[
B = \mu_0 n I,
\qquad
n = \frac{N}{\ell}
\]
($N$ turns over length $\ell$; $n$ = turns per unit length).
$B$ does \emph{not} depend on the radius (ideal long solenoid).

\begin{center}
\begin{tikzpicture}[scale=0.95]
  % solenoid body
  \foreach \x in {0,0.35,...,4.2} {
    \draw[thick] (\x,-0.7) arc (180:360:0.18 and 0.7);
    \draw[thick,dashed] (\x,0.7) arc (0:180:0.18 and 0.7);
  }
  \draw[-{Latex},very thick,negC] (-0.3,0) -- (4.8,0) node[right,font=\small] {$B=\mu_0 n I$};
  \node[font=\scriptsize] at (2.1,-1.35) {current sense $\Rightarrow$ N on the right (RH grip)};
  % equivalent bar magnet
  \begin{scope}[yshift=-2.6cm]
    \draw[thick,fill=blue!15] (0.3,-0.35) rectangle (2.2,0.35);
    \draw[thick,fill=red!20] (2.2,-0.35) rectangle (4.1,0.35);
    \node[font=\small] at (1.25,0) {S}; \node[font=\small] at (3.15,0) {N};
    \node[font=\scriptsize] at (2.2,-0.75) {solenoid behaves like a bar magnet};
    \draw[-{Latex},negC] (-0.2,0) -- (0.3,0);
    \draw[-{Latex},negC] (4.1,0) -- (4.6,0);
  \end{scope}
\end{tikzpicture}
\end{center}

\noindent\textbf{RH grip for a solenoid:} curl fingers around the coil in the
sense of the current; thumb points toward the N-pole end (field inside along the axis).

\worked{2018}{27}{C}{62}{../2018_q27.png}{%
Between the poles the magnet's field runs from N to S (leftward in the figure).
Current out of the paper gives anticlockwise circular $B$ around the wire.
Only at \textbf{R} (below the wire) can the wire's field oppose the magnet's field
and cancel it $\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Electromagnets}

An electromagnet is a current-carrying coil, usually with a soft-iron core.
\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
 & Soft iron & Steel \\
\midrule
Magnetised by a coil? & Easily & Harder \\
Keeps magnetism when $I=0$? & No (temporary) & Yes (permanent magnet) \\
Typical use & Electromagnets, cores, relays & Permanent magnets \\
\bottomrule
\end{tabular}
\end{center}

Ways to strengthen an electromagnet: larger $I$, more turns, soft-iron core,
keep the magnetic circuit short (small air gap).
Using a.c.\ instead of d.c.\ does \emph{not} help for a steady electromagnet
(the field reverses continually).

\begin{mdframed}[style=tipbox]
\noindent\textbf{QB check.}
Increasing $n$ or $I$ raises $B=\mu_0 n I$. Stretching a solenoid at fixed $N$ and
$I$ halves $n$ if length doubles, so $B$ halves.
\end{mdframed}

%======================================================================
\section{Force on a current-carrying conductor}

\subsection{Formula}
A straight wire of length $L$ carrying current $I$ in a magnetic field $\vec B$
experiences
\[
F = B I L \sin\theta,
\]
where $\theta$ is the angle between the current direction and $\vec B$.
Maximum force when the wire is perpendicular to $\vec B$ ($\sin\theta=1$);
zero when parallel.

\subsection{Fleming's left-hand rule}
\begin{center}
\begin{tikzpicture}[scale=1.0]
  % hand schematic
  \draw[thick,fill=orange!15] (0,0) -- (1.8,0.2) -- (1.9,1.6) -- (0.2,1.4) -- cycle;
  \draw[thick,fill=orange!20] (0.3,1.45) -- (0.1,2.5) -- (0.55,2.55) -- (0.7,1.5); % index
  \draw[thick,fill=orange!20] (0.75,1.5) -- (0.95,2.35) -- (1.35,2.3) -- (1.15,1.45); % middle
  \draw[thick,fill=orange!20] (-0.05,0.9) -- (-1.1,1.35) -- (-0.95,1.7) -- (0.15,1.25); % thumb
  \draw[-{Latex},very thick,posC] (-0.2,1.3) -- (-1.6,1.85) node[left,font=\small] {thumb: Force $F$};
  \draw[-{Latex},very thick,negC] (0.4,2.5) -- (0.4,3.3) node[above,font=\small] {1st finger: Field $B$};
  \draw[-{Latex},very thick,blue!50!black] (1.15,2.3) -- (2.3,2.7) node[right,font=\small] {2nd finger: Current $I$};
  \node[font=\scriptsize,align=center] at (0.9,-0.45) {Fleming left hand\\(motor rule)};
\end{tikzpicture}
\end{center}

\noindent Hold the left hand with thumb, first finger and second finger mutually
perpendicular: \textbf{thu\textbf{M}b} = Motion/Force, \textbf{First} finger =
Field, se\textbf{C}ond finger = Current.

\subsection{Catapult field (resultant pattern)}
When a wire sits in an external field, the circular field of the wire adds to the
external field on one side and partially cancels on the other. The wire is pushed
from the \textbf{stronger} (denser lines) side toward the weaker side.

\worked{2013}{26}{C}{42}{../2013_q26.png}{%
Current into the paper $\Rightarrow$ clockwise $B$ around the wire (RH grip).
Lines are denser on the \textbf{left}, so the external field and the wire's field
reinforce there: external $\vec B$ must be \textbf{upward} (S at $X$, N at $Y$).
Force is from dense $\to$ sparse, i.e.\ to the \textbf{right}.
Fleming left hand confirms: $B$ up, $I$ into page $\Rightarrow$ $F$ to the right
$\Rightarrow$ \textbf{C}.}

\worked{2013}{28}{C}{42}{../2013_q28.png}{%
Battery drives current through the rod from $Y$ toward $X$. Viewed from $Y$,
current is into the paper; $\vec B$ is vertically downward.
Fleming left hand: $B$ down, $I$ into page $\Rightarrow$ $F_B$ horizontally
\textbf{to the left} (diagram~C) $\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Force on a moving charge}

A charge $q$ moving at velocity $\vec v$ in a magnetic field feels
\[
\vec F = q\,\vec v\times\vec B
\qquad\text{(magnitude }F=|q|vB\sin\theta\text{)}.
\]
\begin{itemize}
  \item If $q>0$, use Fleming left hand with ``current'' along $\vec v$.
  \item If $q<0$ (e.g.\ electron), the force is \textbf{opposite} to that rule's
        prediction for a positive charge.
  \item $\vec F$ is always perpendicular to $\vec v$, so $|v|$ is unchanged;
        magnetic forces do no work.
\end{itemize}

\qbtext{QB406 PHY14061101}{%
An electron moving towards the right enters a region of a uniform magnetic field
pointing out of the page. What is the direction of the magnetic force acting on it
as it enters the region of the field?
\begin{itemize}[nosep]
  \item[A] Towards the left
  \item[B] Towards the right
  \item[C] Downwards
  \item[D] Upwards
\end{itemize}
}{C}{%
For a \emph{positive} charge moving right in $\vec B$ out of the page, Fleming left
hand gives force \textbf{upward}. An electron has $q<0$, so reverse that:
force is \textbf{downwards} $\Rightarrow$ \textbf{C}.}

\worked{2014}{29}{B}{28}{../2014_q29.png}{%
Conventional current is right$\to$left, so electrons drift left$\to$right.
$V_{PQ}>V_{SR}$ means electrons have piled up on face $SR$ (making it negative).
Force on electrons is toward $SR$. With $\vec v_e$ to the right and
$\vec F_e$ toward $SR$, $\vec F=q\vec v\times\vec B$ requires $\vec B$ from
$Q$ to $P$ $\Rightarrow$ \textbf{B}.
(Do not treat lattice ions as mobile $+$; in metals only electrons drift.)}

\worked{2013}{29}{D}{42}{../2013_q29.png}{%
Free charges in the rotating rod feel $\vec F=q\vec v\times\vec B$.
With $\vec B$ into the page and clockwise motion, positive charges are driven
toward $P$, so $P$ is at higher potential. There is no closed circuit, so
\textbf{no induced current} --- only an e.m.f.\ $\Rightarrow$ \textbf{D}.}

%======================================================================
\section{Parallel current-carrying wires}

Each wire sits in the other's magnetic field, so each feels $F=BIL$.
\begin{itemize}
  \item Currents in the \textbf{same} direction: wires \textbf{attract}.
  \item Currents in \textbf{opposite} directions: wires \textbf{repel}.
\end{itemize}
(The forces are an action--reaction pair.)

\begin{center}
\begin{tikzpicture}[scale=0.95]
  \draw[line width=1.6pt,-{Latex}] (0,-1.2) -- (0,1.4) node[above,font=\small] {$I$};
  \draw[line width=1.6pt,-{Latex}] (2.2,-1.2) -- (2.2,1.4) node[above,font=\small] {$I$};
  \draw[-{Latex},thick,negC] (0.25,0.2) -- (1.95,0.2);
  \draw[-{Latex},thick,negC] (1.95,-0.2) -- (0.25,-0.2);
  \node[font=\scriptsize] at (1.1,-1.55) {same $I$: attract};
  \begin{scope}[xshift=5.0cm]
    \draw[line width=1.6pt,-{Latex}] (0,-1.2) -- (0,1.4) node[above,font=\small] {$I$};
    \draw[line width=1.6pt,-{Latex}] (2.2,1.4) -- (2.2,-1.2) node[below,font=\small] {$I$};
    \draw[-{Latex},thick,posC] (0.25,0) -- (-0.6,0);
    \draw[-{Latex},thick,posC] (1.95,0) -- (2.8,0);
    \node[font=\scriptsize] at (1.1,-1.55) {opposite $I$: repel};
  \end{scope}
\end{tikzpicture}
\end{center}

\worked{2013}{27}{C}{59}{../2013_q27.png}{%
Apply RH grip at $O$ for each equal current.
Three of the four wires produce $\vec B$ into the paper at $O$; wire $R$ produces
$\vec B$ out of the paper. Net field is into the paper.
Removing $R$ removes the opposing contribution and \textbf{increases} $|\vec B|$
at $O$ $\Rightarrow$ \textbf{C}.}

\worked{2014}{26}{A}{58}{../2014_q26.png}{%
Equal distances from $O$. Fields of $P$ and $R$ (both into the paper) are equal
and opposite at $O$ and cancel. Fields of $Q$ (into) and $S$ (out) both point
along $OP$. Resultant is along $\overrightarrow{OP}$ $\Rightarrow$ \textbf{A}.}

\worked{2024}{26}{B}{49}{../2024_q26.png}{%
$I_1$ up the vertical wire $\Rightarrow$ at $MN$ (to the right), RH grip gives
$\vec B$ into the paper. $I_2$ is toward $M$ (to the left).
Fleming left hand: $B$ into page, $I$ left $\Rightarrow$ force on $MN$
\textbf{downward} $\Rightarrow$ \textbf{B}.}

%======================================================================
\section{The d.c.\ motor}

\subsection{Why a coil turns}
Place a rectangular coil carrying current in a uniform $\vec B$ between magnets.
Sides parallel to $\vec B$ feel no force; the two sides perpendicular to $\vec B$
feel equal and opposite forces, forming a \textbf{couple} (torque) that rotates
the coil.

\begin{center}
\begin{tikzpicture}[scale=0.95]
  % magnets
  \draw[thick,fill=red!20] (-0.2,0) rectangle (0.8,2.4);
  \node[font=\small] at (0.3,1.2) {N};
  \draw[thick,fill=blue!15] (4.0,0) rectangle (5.0,2.4);
  \node[font=\small] at (4.5,1.2) {S};
  \draw[-{Latex},negC] (0.9,1.9) -- (3.9,1.9);
  \draw[-{Latex},negC] (0.9,0.5) -- (3.9,0.5);
  \node[font=\scriptsize,negC] at (2.4,2.2) {$B$};
  % coil
  \draw[thick,fill=gray!10] (1.3,0.7) rectangle (3.5,1.7);
  \draw[-{Latex},very thick,posC] (1.3,1.2) -- (1.3,0.15) node[below,font=\scriptsize] {$F$};
  \draw[-{Latex},very thick,posC] (3.5,1.2) -- (3.5,2.25) node[above,font=\scriptsize] {$F$};
  \draw[-{Latex},thick] (2.4,1.2) arc (0:70:0.55);
  \node[font=\scriptsize] at (2.9,1.55) {torque};
  % commutator sketch
  \begin{scope}[xshift=6.3cm,yshift=0.3cm]
    \draw[thick] (0,0.8) circle (0.55);
    \draw[thick,fill=yellow!30] (-0.08,0.25) -- (-0.08,1.35) -- (0.08,1.35) -- (0.08,0.25);
    \draw[thick,fill=gray!40] (-0.55,0.95) rectangle (-0.35,1.35);
    \draw[thick,fill=gray!40] (0.35,0.95) rectangle (0.55,1.35);
    \node[font=\scriptsize] at (0,-0.15) {split-ring};
    \node[font=\scriptsize] at (0,-0.45) {commutator};
    \draw[thick] (-0.9,1.15) -- (-0.55,1.15);
    \draw[thick] (0.55,1.15) -- (0.9,1.15);
    \node[font=\scriptsize] at (-1.15,1.15) {brush};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Role of the split-ring commutator}
When the coil reaches the vertical position the torque would reverse if the
current stayed the same. The \textbf{split-ring commutator} reverses the current
in the coil every half-turn so the torque keeps the same sense and the coil
continues to rotate in one direction.
At the instant the coil plane is perpendicular to $\vec B$, the moment arm is
zero (instantaneous torque zero), but the coil's \textbf{inertia} carries it past
that position.

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistakes --- motors.}
\begin{itemize}
  \item Commutator reverses current in the \emph{coil}, not the battery polarity.
  \item Slip rings (a.c.\ generator) do \emph{not} reverse connections the same way.
  \item Curved pole pieces give a more radial field $\Rightarrow$ more nearly
        constant torque over a cycle.
\end{itemize}
\end{mdframed}

\worked{2015}{24}{B}{44}{../2015_q24.png}{%
At the instant shown, flux linkage is changing at its greatest rate, so induced
e.m.f.\ is maximum (A~true). Lenz: induced current opposes the change --- its
magnetic forces produce a moment opposing rotation (D~true). Force on side $P$
(moving out of the paper) with $\vec B$ as drawn is into the paper (C~true).
The current sense stated in B is the wrong way round $\Rightarrow$ \textbf{B}
is incorrect.}

\worked{2017}{28}{C}{46}{../2017_q28.png}{%
Motional e.m.f.\ $\mathcal{E}=Bdv$ (rod length across the rails is $d$).
Induced current $I=\mathcal{E}/R=Bdv/R$.
Free positive charges in the moving rod feel $\vec F=q\vec v\times\vec B$ toward
$X$, so current through $R$ is from $X$ to $Y$ $\Rightarrow$ \textbf{C}.}

